#!/usr/bin/env python3
import json,sys,datetime as dt
p=sys.argv[1] if len(sys.argv)>1 else 'player_projections.json';o=json.load(open(p));assert o['schema_version']=='1.1.0';assert o['status']=='research';assert o['sportsbook']['active'] is False;assert len(o['players'])>=150;assert len({x['player_id'] for x in o['players']})==len(o['players']);assert sum(x['fantasy_rostered'] for x in o['players'])>=20;assert len(o['matchup_context']['rows'])>=100;assert o['bust_model']['proven'];assert all(0<=x['boom_probability']<=1 and 0<=x['anytime_td_probability']<=1 for x in o['players']);assert all(x['bust_probability'] is None or 0<=x['bust_probability']<=1 for x in o['players']);print({'valid':True,'players':len(o['players']),'matchups':len(o['matchup_context']['rows']),'week':o['matchup_context']['week']})
